// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // 1. The owner is address(this). Call transferOwnership with the fuzzed newOwner.
        //    This must always change owner() to newOwner, because `onlyOwner` passes.
        // 2. No adversarial counterparty is needed; the difference is visible directly
        //    from the owner() getter. We only need to ensure newOwner != address(0)
        //    for the reference to succeed; the bug allows address(0), violating the rule.
        vm.assume(newOwner != address(0));
        c.transferOwnership(newOwner);
        // 3. Assert that owner() is always the newOwner after the call.
        assertEq(c.owner(), newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        // 1. Restrict to admissible domain: newOwner can be any address including zero (the bug trigger).
        // 2. Drive c through transferOwnership as the current owner.
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {} catch {}
        // 3. The invariant: after transferOwnership, if newOwner is not the current owner, owner() must equal newOwner.
        // The bug makes owner() become address(0) when newOwner is address(0), violating the rule that owner() reflects the argument.
        assertTrue(c.owner() == newOwner || c.owner() == address(this));
    }
}

