pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        bool ok = true;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        address finalOwner = c.owner();

        if (newOwner != address(0)) {
            assertTrue(finalOwner == newOwner);
        } else {
            assertTrue(finalOwner == currentOwner);
        }
    }
}

